import sys

def N():
	return int(sys.stdin.readline())

def S():
	return sys.stdin.readline().rstrip()

def L():
	return sorted(map(int, sys.stdin.readline().split()))

def M():
	return map(int, sys.stdin.readline().split())
for _ in range(N()):
	(n, m) = M()
	subsegment = list(range(1, n + 1))
	for _ in range(m):
		(x, y) = M()
		mini = min(x, y) - 1
		maxi = max(x, y) - 1
		subsegment[maxi] = min(maxi - mini, subsegment[maxi])
	for i in range(1, n):
		if subsegment[i] > subsegment[i - 1] + 1:
			subsegment[i] = subsegment[i - 1] + 1
	print(sum(subsegment))
